def editorial():
    result={}
    for line in EDITORIAL_ROWS.splitlines():
        t,score,reason,risk=line.split('|')
        result[t]={'durabilityScore':int(score),'reason':reason,'risk':risk,'asOf':'2026-10-12','basis':'Nitel ürün/iş modeli değerlendirmesi; fiyat, bilanço ve teknik puanlar bu skora dahil değildir.'}
    assert len(result)==36 and all(0<=x['durabilityScore']<=20 for x in result.values())
    return result

def build():
    seeds=[];models={};sources={}
    for row in ROWS.splitlines():
        t,name,sector,revenue,customers,value,econ,future,moat,risk,checks,url=row.split('|')
        v=VERIFICATIONS.get(t,{})
        source_urls=[url]
        if v.get('annualURL'):source_urls.append(v['annualURL'])
        if t in ('ACLS','VECO'):source_urls.append('https://www.axcelisveeco.com/')
        if t=='P':source_urls.append('https://www.sec.gov/Archives/edgar/data/1474432/000147443226000061/pstg-20260503.htm')
        models[t]={'revenueModel':revenue,'customers':customers,'customerValue':value,'economicAnalysis':econ}
        seeds.append({'id':'company-'+t,'ticker':t,'name':name,'sector':SECTORS[sector],'date':'2026-10-12','horizon':'3 yıl','status':'Profil hazır','trend':'Veri bekleniyor','price':'','business':revenue,'future':'Potansiyel tez (yorum): '+future+'\nGerçek gelir, müşteri kullanımı ve nakit üretimiyle doğrulanmalı.','moat':'İncelenecek avantaj: '+moat+'\nTezi zayıflatabilecek risk: '+risk,'financial':'Şirkete özel kontroller: '+checks+'\n','technical':'','entry':'','exit':'','invalidate':'','bull':'','base':'','bear':'','summary':'','sources':'Şirket ve resmi rapor kaynakları:\n'+'\n'.join(source_urls)})
        sources[t]={'issuerURL':url,'annualURL':v.get('annualURL'),'annualFiled':v.get('annualFiled'),'submissionsURL':v.get('submissionsURL'),'verifiedTickers':v.get('activeTickers',[]),'verifiedAsOf':'2026-10-12','note':'İş modeli kaynaklarla açıklanır; ekonomik avantaj ve gelecek tezi araştırma yorumudur.','supplementaryURLs':source_urls[2:]}
    assert len(seeds)==36 and len(models)==36 and len({x['ticker'] for x in seeds})==36
    for name,data in [('expansion-seeds',seeds),('expansion-business-models',models),('expansion-sources',sources),('expansion-ranking-editorial',editorial())]:
        pathlib.Path('dist/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
    print('36 unique company profiles, business models and primary source records written.')
if __name__=='__main__':build()
